// Данные для глоссариев — термины по слизистым и температуре

import type { GlossaryTerm } from '@/components/glossary/glossary-app'

// ============== ГЛОССАРИЙ ПО СЛИЗИСТЫМ ==============
export const MUCOUS_GLOSSARY_TERMS: GlossaryTerm[] = [
  { term: 'Tunica mucosa', latin: 'Слизистая оболочка', definition: 'Выстилает полости органов, сообщающихся с внешней средой: ЖКТ, дыхательные пути, мочеполовая система, конъюнктива глаза.', category: 'Анатомия' },
  { term: 'Lamina propria', latin: 'Собственная пластинка слизистой', definition: 'Рыхлая соединительная ткань под эпителием. Содержит сосуды, нервы, лимфоидную ткань (MALT), макрофаги. Питает эпителий диффузно.', category: 'Слои' },
  { term: 'Lamina muscularis mucosae', latin: 'Мышечная пластинка слизистой', definition: 'Тонкий слой гладких мышц под собственной пластинкой. Формирует складки слизистой, обеспечивает локальные движения и опорожнение желёз.', category: 'Слои' },
  { term: 'Tela submucosa', latin: 'Подслизистая основа', definition: 'Слой под слизистой. Содержит крупные сосуды, нервные стволы и подслизистое сплетение Мейсснера. Формально не входит в слизистую, но функционально связана.', category: 'Слои' },
  { term: 'БАРС', definition: 'Мнемоническая формула 4 функций слизистой: Барьер, Абсорбция, Рецепция, Секреция.', category: 'Формулы' },
  { term: 'ЭПМ', definition: 'Мнемоническая формула 3 слоёв слизистой: Эпителий, Пластинка (собственная), Мышца (мышечная пластинка).', category: 'Формулы' },
  { term: 'ЦВВД', definition: 'Алгоритм клинического осмотра слизистых: Цвет, Влажность, Время капиллярного наполнения, Дефекты.', category: 'Формулы' },
  { term: 'ВКН', latin: 'CRT — Capillary Refill Time', definition: 'Время капиллярного наполнения. Оценивается надавливанием на десну до побледнения, затем отпускают и засекают возврат цвета. Норма: 1–2 секунды.', category: 'Клиническое' },
  { term: 'MALT', latin: 'Mucosa-Associated Lymphoid Tissue', definition: 'Лимфоидная ткань, ассоциированная со слизистыми. Миндалины, пейеровы бляшки, солитарные фолликулы. Обеспечивает местный иммунитет.', category: 'Иммунитет' },
  { term: 'Бокаловидные клетки', latin: 'Goblet cells', definition: 'Одноклеточные железы, выделяющие муцин. Образуют защитный слой слизи на поверхности эпителия.', category: 'Клетки' },
  { term: 'Пилоэрекция', definition: 'Подъём шерсти (гусиная кожа). Создаёт воздушную прослойку-утеплитель при охлаждении. Также встречается при лихорадке (стадия подъёма).', category: 'Физиология' },
  { term: 'Диаскопия', definition: 'Надавливание прозрачным предметом на участок слизистой. Гиперемия при этом бледнеет (кровь в сосудах вытесняется), а петехии и экхимозы — нет.', category: 'Клиническое' },
  { term: 'Петехии', definition: 'Мелкие точечные кровоизлияния (до 2 мм). Не бледнеют при надавливании — кровь уже вышла из сосудов. Признак тромбоцитопении, коагулопатии.', category: 'Патология' },
  { term: 'Экхимозы', definition: 'Крупные кровоизлияния (>3 мм), часто сливаются. Как и петехии, не бледнеют при диаскопии.', category: 'Патология' },
  { term: 'Цианоз', definition: 'Синюшная/фиолетовая окраска слизистых. Указывает на гипоксемию (низкий кислород). Требует срочной оценки проходимости дыхательных путей.', category: 'Патология' },
  { term: 'Иктеричность', latin: 'Jaundice', definition: 'Жёлтая окраска слизистых, склер и вентральной поверхности языка. Причина — накопление билирубина. Дифференцируют: до печени / в печени / после печени.', category: 'Патология' },
  { term: 'Ксероз', latin: 'Xerosis', definition: 'Патологическая сухость слизистых. Возникает при дегидратации, лихорадке, снижении секреции слюны, приёме атропина, ХБП.', category: 'Патология' },
  { term: 'Эрозия', definition: 'Поверхностный дефект слизистой в пределах эпителия, не выходящий за базальную мембрану. Заживает без рубца.', category: 'Патология' },
  { term: 'Язва', latin: 'Ulcer', definition: 'Глубокий дефект слизистой, проникающий за базальную мембрану в собственную пластинку или глубже. Заживает с рубцом, может кровоточить.', category: 'Патология' },
  { term: 'Вазодилатация', definition: 'Расширение кровеносных сосудов. Усиливает кровоток → слизистая краснеет. Наблюдается при воспалении, лихорадке, тепловом ударе.', category: 'Физиология' },
  { term: 'Вазоконстрикция', definition: 'Сужение кровеносных сосудов. Уменьшает кровоток → слизистая бледнеет. Наблюдается при шоке, кровопотере, охлаждении.', category: 'Физиология' },
]

// ============== ГЛОССАРИЙ ПО ТЕМПЕРАТУРЕ ==============
export const TEMPERATURE_GLOSSARY_TERMS: GlossaryTerm[] = [
  { term: 'Афферентные сигналы', definition: 'Импульсы от периферии (кожа, внутренние органы) к гипоталамусу. Несут информацию: «там холодно» или «там жарко».', category: 'Физиология' },
  { term: 'Вазоконстрикция', definition: 'Сосуды сузились → тепло сохраняется внутри тела (бледность кожных покровов и слизистых). Активируется при охлаждении и шоке.', category: 'Физиология' },
  { term: 'Вазодилатация', definition: 'Сосуды расширились → тепло уходит наружу через кожу (краснота). Активируется при перегреве и воспалении.', category: 'Физиология' },
  { term: 'Гомеостаз', definition: 'Способность системы сохранять постоянство внутренней среды. Температура тела — один из гомеостатических параметров.', category: 'Физиология' },
  { term: 'Гипоталамус', latin: 'Hypothalamus', definition: 'Главный центр терморегуляции. Преоптическая область работает как умный термостат: сравнивает температуру крови с уставкой и управляет реакциями.', category: 'Анатомия' },
  { term: 'ДВС-синдром', latin: 'Диссеминированное внутрисосудистое свёртывание', definition: 'Кровь свернулась в мелких сосудах, факторы свёртывания израсходованы → начинается кровотечение. Опасное состояние, часто при сепсисе и тепловом ударе.', category: 'Патология' },
  { term: 'Конвекция', definition: 'Тепло уносится потоком воздуха или жидкости от поверхности тела. Один из механизмов теплоотдачи.', category: 'Физика' },
  { term: 'Кондукция', definition: 'Тепло передаётся при прямом контакте (например, лёжа на холодном кафеле). Один из механизмов теплоотдачи.', category: 'Физика' },
  { term: 'Лихорадка', latin: 'Febris', definition: 'Регулируемое повышение температуры тела. Пирогены заставляют гипоталамус повысить «уставку» термостата — защитная реакция против инфекции.', category: 'Патология' },
  { term: 'Гипертермия', definition: 'Нерегулируемый перегрев. Уставка гипоталамуса нормальная, но охлаждение не справляется (тепловой удар, злокачественная гипертермия).', category: 'Патология' },
  { term: 'Гипотермия', definition: 'Снижение температуры ядра ниже нормы (<37.5 °C у собак, <38.0 °C у кошек). Причины: шок, анестезия, охлаждение, гипотиреоз.', category: 'Патология' },
  { term: 'Излучение', definition: 'Тепло излучается в виде инфракрасных волн. Главный механизм теплоотдачи в покое у животных.', category: 'Физика' },
  { term: 'Испарение', definition: 'Тепло уходит с испаряющейся влагой (пот, слюна, слизь). У собак и кошек — через panting (частое дыхание с открытым ртом).', category: 'Физика' },
  { term: 'Мультилокулярные включения', definition: 'Много мелких капелек жира в одной клетке. Признак бурой жировой ткани (BAT).', category: 'Гистология' },
  { term: 'Пирогены', definition: 'Вещества, вызывающие лихорадку. Внешние: бактерии (липополисахариды), вирусы. Внутренние: цитокины (ИЛ-1, ИЛ-6, ФНО-α).', category: 'Патология' },
  { term: 'Пилоэрекция', definition: 'Подъём шерсти («гусиная кожа»). Создаёт воздушную прослойку-утеплитель при охлаждении.', category: 'Физиология' },
  { term: 'Полипноэ', definition: 'Учащённое дыхание. У собак и кошек — основной механизм охлаждения (испарение с языка и слизистых).', category: 'Физиология' },
  { term: 'Простагландин E2', latin: 'PGE2', definition: 'Медиатор лихорадки. Синтезируется в гипоталамусе под действием пирогенов, повышает уставку термостата.', category: 'Биохимия' },
  { term: 'Стадии лихорадки', definition: '3 фазы: Подъём (Incrementi) — озноб, бледность; Разгар (Fastigii) — жар, краснота; Падение (Decrementi) — литическое (медленно) или критическое (резко).', category: 'Патология' },
  { term: 'Термогенин', latin: 'UCP1 — Uncoupling Protein 1', definition: 'Белок бурой жировой ткани. Разобщает окислительное фосфорилирование: вместо АТФ энергия выделяется в виде тепла. Особенно важен у щенков и котят.', category: 'Биохимия' },
  { term: 'Бурая жировая ткань', latin: 'BAT — Brown Adipose Tissue', definition: 'Специализированная жировая ткань для несократительного термогенеза. Много митохондрий и термогенина (UCP1). У новорождённых и мелких животных.', category: 'Анатомия' },
  { term: 'Хроматолиз', definition: 'Растворение тигроида (нисслевского вещества) в теле нейрона. Признак повреждения нервной клетки, в т.ч. от перегрева.', category: 'Патология' },
  { term: 'Тепловой удар', definition: 'Опасная гипертермия от внешнего перегрева (например, собака в машине). Температура может превысить 41 °C → ДВС-синдром, некроз органов.', category: 'Патология' },
]

// ============== ГЛОССАРИЙ ПО СЕРДЦУ (пока базовый — будет наполняться) ==============
export const HEART_GLOSSARY_TERMS: GlossaryTerm[] = [
  { term: 'Большой круг кровообращения', definition: 'Левый желудочек → аорта → органы → полые вены → правое предсердие. Обеспечивает ткани кислородом.', category: 'Физиология' },
  { term: 'Малый круг кровообращения', definition: 'Правый желудочек → лёгочный ствол → лёгкие → лёгочные вены → левое предсердие. Здесь кровь насыщается кислородом.', category: 'Физиология' },
  { term: 'Аорта', latin: 'Aorta', definition: 'Самая крупная артерия тела. Выходит из левого желудочка через аортальный клапан. Несёт оксигенированную кровь ко всем органам.', category: 'Сосуды' },
  { term: 'Лёгочный ствол', latin: 'Truncus pulmonalis', definition: 'Выходит из правого желудочка через лёгочный клапан. Несёт венозную кровь в лёгкие (единственная артерия с венозной кровью).', category: 'Сосуды' },
  { term: 'Митральный клапан', latin: 'Valva atrioventricularis sinistra', definition: 'Двухстворчатый AV-клапан между левым предсердием и левым желудочком. Открыт в диастолу, закрыт в систолу.', category: 'Клапаны' },
  { term: 'Трикуспидальный клапан', latin: 'Valva atrioventricularis dextra', definition: 'Трёхстворчатый AV-клапан между правым предсердием и правым желудочком.', category: 'Клапаны' },
  { term: 'Аортальный клапан', latin: 'Valva aortae', definition: 'Полулунный клапан из 3 створок в основании аорты. Закрыт в диастолу, открыт в систолу.', category: 'Клапаны' },
  { term: 'Лёгочный клапан', latin: 'Valva trunci pulmonalis', definition: 'Полулунный клапан в основании лёгочного ствола. Закрыт в диастолу, открыт в систолу.', category: 'Клапаны' },
  { term: 'Систола', definition: 'Фаза сокращения желудочков (~0.4 цикла). AV-клапаны закрыты, полулунные открыты. Кровь выбрасывается в аорту и лёгочный ствол.', category: 'Физиология' },
  { term: 'Диастола', definition: 'Фаза расслабления желудочков (~0.6 цикла). AV-клапаны открыты, полулунные закрыты. Желудочки наполняются кровью.', category: 'Физиология' },
  { term: 'Сердечный цикл', definition: 'Полный цикл от одной систолы до следующей. У собак 60–140 циклов/мин (ЧСС), у кошек 140–220.', category: 'Физиология' },
  { term: 'M-mode', latin: 'Motion-mode', definition: 'Режим одномерного УЗИ, показывающий движение структур сердца во времени. X — время, Y — глубина.', category: 'Диагностика' },
]

// ============== ГЛОССАРИЙ ПО ГИДРАТАЦИИ ==============
export const HYDRATION_GLOSSARY_TERMS: GlossaryTerm[] = [
  { term: 'Гидратация', definition: 'Состояние водного баланса организма. Вода составляет ~60% массы тела у взрослых собак и кошек. Поддерживается балансом между потреблением и потерями жидкости.', category: 'Основы' },
  { term: 'Дегидратация', latin: 'Dehydration', definition: 'Патологическое состояние, при котором организм теряет больше воды, чем получает. Приводит к уменьшению объёма жидкости в водных секторах (ICF и ECF).', category: 'Патология' },
  { term: 'ICF', latin: 'Intracellular Fluid — внутриклеточная жидкость', definition: 'Жидкость внутри клеток. Составляет ~2/3 всей воды организма (~40% массы тела). Главный катион — K+.', category: 'Водные секторы' },
  { term: 'ECF', latin: 'Extracellular Fluid — внеклеточная жидкость', definition: 'Жидкость вне клеток. Составляет ~1/3 всей воды (~20% массы тела). Делится на внутрисосудистую (плазма, ~5%) и интерстициальную (~15%). Главный катион — Na+.', category: 'Водные секторы' },
  { term: 'Изотоническая дегидратация', definition: 'Самый частый тип. Вода и электролиты теряются в равной пропорции. Осмоляльность плазмы нормальная. Причины: рвота, диарея, кровопотеря.', category: 'Классификация' },
  { term: 'Гипертоническая дегидратация', definition: 'Потеря воды превышает потерю электролитов. Осмоляльность плазмы повышена. Клетки сморщиваются (пликореп). Причины: недостаток воды, диабет, лихорадка, panting.', category: 'Классификация' },
  { term: 'Гипотоническая дегидратация', definition: 'Потеря электролитов превышает потерю воды. Осмоляльность плазмы понижена. Клетки набухают. Причины: болезнь Аддисона, диуретики, почечная недостаточность.', category: 'Классификация' },
  { term: 'Тургор кожи', latin: 'Skin turgor', definition: 'Эластичность кожи. Оценивается поднятием кожной складки на холке/спине. В норме расправляется мгновенно. При дегидратации — медленно (>1-2 сек).', category: 'Клиническое' },
  { term: 'Натрий', latin: 'Na+ — Natrium', definition: 'Главный катион внеклеточной жидкости. Определяет осмоляльность плазмы и распределение воды между ICF и ECF. Норма в сыворотке: 140-150 ммоль/л.', category: 'Электролиты' },
  { term: 'Калий', latin: 'K+ — Kalium', definition: 'Главный катион внутриклеточной жидкости. Критичен для нервно-мышечной возбудимости и сердечного ритма. Норма: 3.5-5.5 ммоль/л.', category: 'Электролиты' },
  { term: 'Хлор', latin: 'Cl- — Chlorum', definition: 'Главный анион ECF. Следует за Na+. Норма: 105-115 ммоль/л. Важен для кислотно-щелочного баланса.', category: 'Электролиты' },
  { term: 'Na+/K+-АТФаза', latin: 'Натриево-калиевый насос', definition: 'Фермент в мембране клеток. Перекачивает 3 Na+ наружу и 2 K+ внутрь против градиента концентрации, тратя АТФ. Поддерживает разность концентраций между ICF и ECF.', category: 'Физиология' },
  { term: 'Осмоляльность', definition: 'Концентрация растворённых частиц в жидкости (мОсм/кг). Норма плазмы: 290-310 мОсм/кг. Определяется в основном Na+, глюкозой и мочевиной.', category: 'Физиология' },
  { term: 'Лактатный раствор Рингера', latin: 'Ringer\'s Lactate, Hartmann\'s solution', definition: 'Сбалансированный кристаллоид, близкий к плазме по электролитному составу. Содержит Na+, K+, Ca2+, Cl- и лактат (метаболизируется в бикарбонат — коррекция ацидоза). Препарат выбора для реанимации.', category: 'Терапия' },
  { term: '0,9% NaCl', latin: 'Физиологический раствор', definition: 'Изотонический раствор хлорида натрия. Содержит только Na+ и Cl-. Не содержит буфера (не корректирует ацидоз). Подходит для пациентов с гипернатриемией.', category: 'Терапия' },
  { term: 'Кристаллоиды', definition: 'Растворы с низкомолекулярными растворёнными веществами, свободно проходят через капиллярную мембрану. 1/3 остаётся в сосудах, 2/3 уходит в интерстиций. Примеры: Рингер-лактат, 0.9% NaCl.', category: 'Терапия' },
  { term: 'Коллоиды', definition: 'Растворы с крупномолекулярными частицами, дольше задерживаются в сосудистом русле. Примеры: гидроксиэтилкрахмал, желатин, альбумин. Быстрее восстанавливают объём при шоке.', category: 'Терапия' },
  { term: 'Степени дегидратации', definition: 'Лёгкая (<5%): слегка сухие слизистые. Умеренная (5-8%): кожная складка >1 сек, сухие слизистые, запавшие глаза. Тяжёлая (>8%): шок, холодные конечности, складка >2 сек, угнетение сознания.', category: 'Клиническое' },
  { term: 'Шок', definition: 'Состояние острой недостаточности перфузии тканей. Причины при дегидратации: гиповолемический (потеря жидкости). Признаки: тахикардия, слабый пульс, гипотензия, холодные конечности, угнетение.', category: 'Патология' },
  { term: 'Ацидоз', definition: 'Снижение pH крови (<7.35). Часто сопутствует тяжёлой дегидратации (потеря бикарбоната при диарее, лактат при гипоперфузии). Корректируется лактатным раствором Рингера.', category: 'Кислотно-щелочной баланс' },
]

// ============== ГЛОССАРИЙ ПО ЛИМФАТИЧЕСКОЙ СИСТЕМЕ ==============
export const LYMPH_GLOSSARY_TERMS: GlossaryTerm[] = [
  { term: 'Лимфа', definition: 'Прозрачная жидкость, циркулирующая по лимфатическим сосудам. Содержит воду, белки, липиды (после еды — хилус) и лимфоциты. Образуется из тканевой жидкости.', category: 'Основы' },
  { term: 'Лимфатический капилляр', definition: 'Слепо начинающиеся трубочки в тканях. Стенка проницаема для жидкости и белков, но клапаны не дают обратного тока. Начало лимфатической системы.', category: 'Анатомия' },
  { term: 'Лимфоузел', latin: 'Lymphonodus / Nodus lymphaticus', definition: 'Орган-фильтр на пути лимфатических сосудов. Содержит B- и T-лимфоциты, макрофаги. Здесь происходит иммунный ответ и фильтрация антигенов.', category: 'Анатомия' },
  { term: 'Грудной проток', latin: 'Ductus thoracicus', definition: 'Самый крупный лимфатический сосуд. Собирает лимфу со всей нижней половины тела и левой половины верха. Впадает в левую вену.', category: 'Протоки' },
  { term: 'Правый лимфатический проток', definition: 'Короткий проток. Собирает лимфу от правой половины головы, шеи и правой передней лапы. Впадает в правую вену.', category: 'Протоки' },
  { term: 'Хилус', latin: 'Chyle', definition: 'Молочно-белая лимфа из кишечника после еды. Содержит липиды (жиры). Жиры идут через лимфу, а не через кровь напрямую.', category: 'Физиология' },
  { term: 'Капсула лимфоузла', definition: 'Плотная соединительнотканная оболочка, покрывающая лимфоузел снаружи. Защищает и поддерживает форму.', category: 'Гистология' },
  { term: 'Трабекулы', definition: 'Внутренние перегородки-балки, отходящие от капсулы вглубь узла. Держат каркас.', category: 'Гистология' },
  { term: 'Кора лимфоузла', latin: 'Cortex', definition: 'Внешний слой лимфоузла. Зона B-лимфоцитов. Содержит фолликулы с герминативными центрами (где рождаются новые клетки при атаке антигена).', category: 'Гистология' },
  { term: 'Паракортекс', latin: 'Paracortex', definition: 'Глубокая кора лимфоузла. Зона T-лимфоцитов. Содержит HEV (венулы с высоким эндотелием) — ворота для миграции лимфоцитов из крови.', category: 'Гистология' },
  { term: 'Мозговое вещество', latin: 'Medulla', definition: 'Центральная часть лимфоузла. Содержит мозговые тяжи (плазматические клетки, производящие антитела) и синусы (фильтры с макрофагами).', category: 'Гистология' },
  { term: 'HEV', latin: 'High Endothelial Venules — венулы с высоким эндотелием', definition: 'Специальные кровеносные сосуды в паракортексе. Через них лимфоциты мигрируют из крови в лимфоузел.', category: 'Гистология' },
  { term: 'B-лимфоциты', definition: 'В-клетки — лимфоциты, созревающие в костном мозге. Находятся в коре лимфоузла. Дифференцируются в плазматические клетки, производящие антитела.', category: 'Иммунология' },
  { term: 'T-лимфоциты', definition: 'Т-клетки — лимфоциты, созревающие в тимусе. Находятся в паракортексе. T-хелперы координируют ответ, T-киллеры убивают заражённые клетки.', category: 'Иммунология' },
  { term: 'Макрофаги', definition: 'Фагоцитирующие клетки в синусах лимфоузла. Поглощают и переваривают мусор, бактерии, остатки клеток. «Вышибалы» лимфоузла.', category: 'Иммунология' },
  { term: 'Дендритные клетки', definition: 'Клетки, захватывающие антиген в тканях и мигрирующие в лимфоузел, чтобы «показать» его T-клеткам. Запускают адаптивный иммунный ответ.', category: 'Иммунология' },
  { term: 'Лимфангионы', definition: 'Сегменты лимфатических сосудов с собственными гладкомышечными клетками. Сокращаются ритмически, проталкивая лимфу вперёд (нет сердца-насоса).', category: 'Физиология' },
  { term: 'Лимфаденопатия', definition: 'Общий термин для любого увеличения лимфоузла. Не диагноз, а симптом. Причины: реактивная гиперплазия, лимфаденит, неоплазия.', category: 'Патология' },
  { term: 'Лимфаденит', definition: 'Воспаление лимфоузла. Может быть гнойным (бактериальная инфекция). Узел болезненный, горячий. Структура разрушается нейтрофилами.', category: 'Патология' },
  { term: 'Лимфома', definition: 'Злокачественная опухоль из лимфоцитов (свой рак). Узлы огромные, сливаются в комки. На разрезе однородные серо-белые, «рыбье мясо». Самая частая гемолимфопролиферативная опухоль у собак.', category: 'Патология' },
  { term: 'Метастазы', definition: 'Опухолевые клетки из другого органа, попавшие в лимфоузел лимфогенным путём. В узле видны чужеродные очаги или кровоизлияния.', category: 'Патология' },
  { term: 'Лимфангит', definition: 'Воспаление стенок лимфатических сосудов. Видны красные болезненные полосы под кожей. Часто при стрептококковой инфекции.', category: 'Патология' },
  { term: 'Лимфедема', definition: 'Отёк тканей из-за застоя лимфы. Белковая жидкость накапливается в интерстиции. Бывает врождённой или после травм/операций.', category: 'Патология' },
  { term: 'Хилоторакс', definition: 'Скопление молочной лимфы (хилуса) в плевральной полости. Возникает при разрыве грудного протока. «Страшный сон хирурга».', category: 'Патология' },
  { term: '5 параметров пальпации', definition: 'Размер, Форма, Консистенция, Подвижность, Болезненность. Оцениваются при пальпации каждого лимфоузла. Каменный + неподвижный + безболезненный = онкология.', category: 'Клиническое' },
]

// ============== ГЛОССАРИЙ ПО ДЫХАТЕЛЬНОЙ СИСТЕМЕ ==============
export const RESPIRATORY_GLOSSARY_TERMS: GlossaryTerm[] = [
  { term: 'Ателектаз', definition: 'Спавшаяся, «сдувшаяся» часть лёгкого. Как воздушный шарик, из которого выпустили воздух, и он слипся сам с собой.', category: 'Патология' },
  { term: 'Аускультация', definition: 'Выслушивание звуков тела с помощью стетоскопа. «Слушать, о чём шепчут (или кричат) лёгкие».', category: 'Клиническое' },
  { term: 'Бокаловидные клетки', definition: 'Клетки-фабрики в слизистой, производящие слизь (муцин). Внутренний увлажнитель и ловушка для пыли.', category: 'Гистология' },
  { term: 'Брадипноэ', definition: 'Патологически замедленное, редкое дыхание. Организм «тормозит»: передозировка, травма мозга, гипотермия.', category: 'Патология' },
  { term: 'Везикулярное дыхание', definition: 'Нормальный, мягкий, «дующий» звук здоровых лёгких на вдохе. Шуршание листвы на лёгком ветру.', category: 'Звуки' },
  { term: 'Вентиляция', definition: 'Механический процесс обмена воздуха (вдох-выдох). Работа кузнечных мехов или насоса.', category: 'Физиология' },
  { term: 'Гепатизация', definition: 'Состояние, когда воспаленное лёгкое становится плотным и безвоздушным. Лёгкое по плотности как печень (Hepar). Звук через него проходит отлично, но газа оно не меняет.', category: 'Патология' },
  { term: 'Гиперкапния', definition: 'Избыток углекислого газа (CO₂) в крови. Главный «будильник» для дыхательного центра: «Эй, пора выдохнуть!».', category: 'Патология' },
  { term: 'Гиперестезия', definition: 'Повышенная, болезненная чувствительность. «Больно трогать» — например, рёбра при переломе или плеврите.', category: 'Клиническое' },
  { term: 'Гипоксемия', definition: 'Пониженное содержание кислорода именно в артериальной крови.', category: 'Патология' },
  { term: 'Гипоксия', definition: 'Нехватка кислорода в тканях организма в целом. Гипоксемия (в крови) быстро приводит к гипоксии (в мозге и органах).', category: 'Патология' },
  { term: 'Диспноэ (Одышка)', definition: 'Затруднённое дыхание, чувство нехватки воздуха. Бывает: инспираторная (трудно вдохнуть — проблема в горле/трахее), экспираторная (трудно выдохнуть — бронхи, астма), смешанная (трудно и то, и другое — лёгкие или плевра).', category: 'Патология' },
  { term: 'Инспирация', definition: 'Вдох. Активный процесс расширения грудной клетки.', category: 'Физиология' },
  { term: 'Коллапс трахеи', definition: 'Сплющивание трахеи из-за дряблости хрящевых колец. Классический «гусиный гудок» у йорков и шпицев при возбуждении.', category: 'Патология' },
  { term: 'Крепитация', definition: 'Патологический звук «треска» или «хруста снега» в лёгких. Звук, с которым слипшиеся от жидкости альвеолы с хлопком разлепляются на вдохе (отёк, пневмония).', category: 'Звуки' },
  { term: 'Мукоцилиарный клиренс', definition: 'Механизм самоочищения дыхательных путей. «Эскалатор»: реснички эпителия выметают слизь с пылью и микробами вверх, к глотке.', category: 'Физиология' },
  { term: 'Ортопноэ', definition: 'Вынужденная поза для облегчения дыхания. Животное стоит/сидит, широко расставив передние лапы и вытянув шею. «Поза отчаяния».', category: 'Клиническое' },
  { term: 'Парадоксальное дыхание', definition: 'Аномалия биомеханики: при вдохе грудь расширяется, а живот втягивается внутрь. Диафрагма сломана или парализована — грудная клетка работает как пылесос, засасывая живот внутрь.', category: 'Патология' },
  { term: 'Перкуссия', definition: 'Выстукивание пальцем по грудной клетке. Как выбор арбуза: воздух звенит (ясный звук), жидкость или плотная ткань молчат (тупой звук).', category: 'Клиническое' },
  { term: 'Плевральный выпот', definition: 'Скопление жидкости в плевральной полости (между лёгким и стенкой груди). Жидкость «топит» нижние отделы лёгких и работает как звукоизолирующая подушка для стетоскопа.', category: 'Патология' },
  { term: 'Пневмоторакс', definition: 'Свободный воздух в плевральной полости. Лёгкое сдувается, как проколотый шарик, потому что нарушился вакуум.', category: 'Патология' },
  { term: 'Пневмоциты I типа', definition: 'Плоские клетки, образующие тонкие стенки альвеол. Покрывают 95% поверхности. Через них идёт газ.', category: 'Гистология' },
  { term: 'Пневмоциты II типа', definition: 'Кубические клетки — производители сурфактанта. Не дают альвеолам слипнуться.', category: 'Гистология' },
  { term: 'Полипноэ', definition: 'Частое, поверхностное дыхание с открытым ртом. У собак в жару — норма (охлаждение). У кошек — всегда патология и красный флаг!', category: 'Патология' },
  { term: 'Рестрикция', definition: 'Ограничение возможности лёгкого расправиться. Лёгкому «тесно» из-за жидкости, воздуха или опухоли снаружи.', category: 'Патология' },
  { term: 'SRR (Sleeping Respiratory Rate)', definition: 'Частота дыхательных движений во сне. Золотой стандарт кардиологии. Должна быть строго < 30 в минуту. Лучший способ проверить сердце без стресса клиники.', category: 'Клиническое' },
  { term: 'Стридор', definition: 'Громкий, грубый, свистящий или хрипящий звук, слышный на расстоянии. Признак сужения верхних дыхательных путей (гортань, трахея, инородное тело).', category: 'Звуки' },
  { term: 'Сурфактант', definition: 'Смесь веществ, выстилающая альвеолы изнутри. «Мыльная пленка», которая снижает поверхностное натяжение и не даёт альвеолам схлопнуться на выдохе.', category: 'Гистология' },
  { term: 'Тахипноэ', definition: 'Патологически учащённое дыхание (>30–40 в мин в покое).', category: 'Патология' },
  { term: 'Хеморецепторы', definition: 'Биологические «датчики» в мозге и сосудах. Чуют уровень O₂, CO₂ и кислотность крови, отдавая команду мозгу: «Дыши чаще!» или «Дыши реже!».', category: 'Физиология' },
  { term: 'Хрипы крупнопузырчатые', definition: 'Звук «бульканья» в крупных бронхах. Воздух проходит через лужу слизи, гноя или крови (тяжёлая пневмония).', category: 'Звуки' },
  { term: 'Хрипы мелкопузырчатые', definition: 'Тонкий треск. Звук трения пряди волос прямо у уха. Альвеолы со слипшимися стенками разлепляются на вдохе (отёк, фиброз).', category: 'Звуки' },
  { term: 'Хрипы свистящие (Wheezes)', definition: 'Длительный музыкальный свист, чаще на выдохе. Воздух с трудом протискивается через резко спазмированные бронхи (астма кошек).', category: 'Звуки' },
  { term: 'Шум трения плевры', definition: 'Грубый, поверхностный звук. Звук «скрипа новой кожаной сумки» или наждачной бумаги. Воспалённые, шершавые листки плевры трутся друг о друга без смазки.', category: 'Звуки' },
  { term: 'Цианоз', definition: 'Синюшное окрашивание слизистых оболочек. Поздний и грозный признак того, что в крови критически мало кислорода (много «пустого» гемоглобина).', category: 'Клиническое' },
  { term: 'Экспирация', definition: 'Выдох. В норме пассивный процесс. Лёгкие сдуваются сами за счёт своей эластичности, как резиновый мяч.', category: 'Физиология' },
  { term: 'Эупноэ', definition: 'Нормальное, спокойное, ритмичное дыхание без видимых усилий. Мечта любого ветеринарного врача.', category: 'Физиология' },
  { term: 'Дыхание Куссмауля', definition: 'Глубокое, шумное дыхание. Кислота в крови — организм «выдувает» CO₂ (метаболический ацидоз).', category: 'Патология' },
  { term: 'Дыхание Чейна-Стокса', definition: 'Волна нарастает → пик → спад → апноэ. Поражение мозга или терминальная сердечная недостаточность.', category: 'Патология' },
  { term: 'Дыхание Биота', definition: 'Хаос с паузами. Прямое повреждение продолговатого мозга.', category: 'Патология' },
]

// ============== ГЛОССАРИЙ ПО ПУЛЬСУ И АРТЕРИАЛЬНОМУ ДАВЛЕНИЮ ==============
export const PULSE_GLOSSARY_TERMS: GlossaryTerm[] = [
  // Методы исследования
  { term: 'Аускультация', latin: 'Auscultatio', definition: 'Выслушивание звуков сердца и лёгких с помощью стетоскопа. Даёт информацию о работе клапанов, ритме и шуме.', category: 'Методы' },
  { term: 'Пальпация', latin: 'Palpatio', definition: 'Ощупывание поверхности тела, органов или сосудов для определения их физических свойств (размера, формы, пульсации). Не использовать большой палец — в нём есть собственная пульсация.', category: 'Методы' },
  { term: 'Перкуссия', definition: 'Выстукивание грудной клетки пальцем для определения плотности подлежащих тканей. Воздух = ясный звук, жидкость/плотная ткань = тупой.', category: 'Методы' },
  // Гемодинамика
  { term: 'Пульс', latin: 'Pulsus — удар, толчок', definition: 'Периодические ритмичные колебания стенки артерии от выброса крови левым желудочком в аорту во время систолы. Это ВОЛНА давления, бегущая по эластичной трубе, а не сама бегущая кровь.', category: 'Гемодинамика' },
  { term: 'Пульсовая волна', definition: 'Волна растяжения артериальной стенки, бегущая от аорты к периферии. Скорость 4–10 м/с (сама кровь течёт 0,5 м/с). Метафора — «мексиканская волна» на стадионе.', category: 'Гемодинамика' },
  { term: 'Ударный объем (УО)', latin: 'Stroke Volume, SV', definition: 'Количество крови, выбрасываемое левым желудочком в аорту за одно сокращение. Определяет величину (амплитуду) пульса.', category: 'Гемодинамика' },
  { term: 'Минутный объем кровообращения (МОК)', latin: 'Cardiac Output, CO', definition: 'Объём крови, выбрасываемый сердцем за минуту. Формула: МОК = УО × ЧСС.', category: 'Гемодинамика' },
  { term: 'Периферическое сопротивление сосудов (ПСС)', latin: 'Systemic Vascular Resistance, SVR', definition: 'Сопротивление току крови, создаваемое мелкими артериями и артериолами. Основной фактор, определяющий уровень диастолического давления.', category: 'Гемодинамика' },
  { term: 'Перфузия', definition: 'Процесс прохождения крови через капилляры органов, доставляющий кислород и питательные вещества. То, ради чего существует вся гемодинамика.', category: 'Гемодинамика' },
  { term: 'Эластичность сосудистой стенки', definition: 'Способность tunica media растягиваться при систоле и спадаться в диастолу. Определяет скорость распространения пульсовой волны и её форму.', category: 'Гемодинамика' },
  // Фазы сердечного цикла
  { term: 'Систола', definition: 'Фаза сокращения сердечной мышцы, выталкивающей кровь в сосудистое русло. В это время выбрасывается ударный объем.', category: 'Сердечный цикл' },
  { term: 'Диастола', definition: 'Фаза расслабления, во время которой полости сердца заполняются кровью. Эластические волокна аорты спадаются, поддерживая кровоток до следующей систолы.', category: 'Сердечный цикл' },
  // Артериальное давление
  { term: 'Систолическое АД (САД)', definition: 'Максимальное давление в артериях в момент систолы. Отражает силу выброса и ударный объем. Норма у собак: 110–160 мм рт. ст., у кошек: 120–170.', category: 'АД' },
  { term: 'Диастолическое АД (ДАД)', definition: 'Минимальное давление в момент диастолы. Отражает тонус периферических сосудов (ПСС). Норма у собак: 60–90, у кошек: 70–100.', category: 'АД' },
  { term: 'Пульсовое давление', definition: 'Разница между САД и ДАД (САД − ДАД). Отражает ударный объем и эластичность аорты. Норма 30–50 мм рт. ст.', category: 'АД' },
  { term: 'Среднее артериальное давление (MAP)', definition: 'Среднее давление за цикл. Формула: MAP = ДАД + 1/3 × (САД − ДАД). Главный показатель перфузии органов.', category: 'АД' },
  { term: 'Гипертензия', definition: 'Стойкое повышение АД: у собак САД > 160, у кошек > 170 мм рт. ст. У кошек чаще вторичная (ХБП, гипертиреоз), у собак — почечная или эндокринная.', category: 'Патология АД' },
  { term: 'Гипотензия', definition: 'Патологическое снижение АД: САД < 90 мм рт. ст. Причины: шок, кровопотеря, сепсис, передозировка гипотензивных, сердечная недостаточность.', category: 'Патология АД' },
  { term: 'ГЛПС', definition: 'Гипертрофия левого желудочка сердца. Адаптивная реакция на хроническую перегрузку давлением (гипертензия). Стенка утолщается, полость уменьшается → диастолическая дисфункция.', category: 'Патология АД' },
  { term: 'NT-proBNP', definition: 'N-терминальный фрагмент мозгового натрийуретического пептида. Биомаркер растяжения миокарда. Повышен при сердечной недостаточности. У кошек — ключевой скрининг кардиомиопатий.', category: 'Биомаркёры' },
  // Сосудистые реакции
  { term: 'Вазодилатация', definition: 'Расширение просвета сосудов за счёт расслабления гладкой мускулатуры tunica media. Снижает ПСС и АД. Медиаторы: оксид азота (NO), брадикинин.', category: 'Сосуды' },
  { term: 'Вазоконстрикция', definition: 'Сужение просвета сосудов за счёт сокращения гладкомышечных клеток. Повышает ПСС и АД. Медиаторы: эндотелин, катехоламины, ангиотензин II.', category: 'Сосуды' },
  // Структуры сосудов
  { term: 'Tunica intima', definition: 'Внутренняя оболочка артерии. «Подкладка» куртки. Выстлана эндотелием, выделяет вазоактивные вещества (NO для расширения, эндотелин для сужения).', category: 'Анатомия' },
  { term: 'Tunica media', definition: 'Средняя оболочка — самая толстая и важная для пульса. Состоит из гладкомышечных клеток и эластических волокон. «Пружина/утеплитель». Растягивается при систоле, спадается в диастолу.', category: 'Анатомия' },
  { term: 'Tunica adventitia', definition: 'Наружная оболочка артерии. Рыхлая соединительная ткань. Содержит сосуды сосудов (vasa vasorum) и нервные волокна, регулирующие тонус.', category: 'Анатомия' },
  { term: 'Эндотелий', definition: 'Однослойный пласт плоских клеток, выстилающий внутреннюю поверхность сосудов. Не просто барьер, а активный эндокринный орган: регулирует тонус, свёртывание крови, воспаление.', category: 'Гистология' },
  { term: 'Vasa vasorum', definition: '«Сосуды сосудов» — крошечные капилляры, питающие стенку крупных артерий (aорта, v. cava). Сама стенка слишком толстая, чтобы питаться диффузно из просвета.', category: 'Анатомия' },
  // Регуляция АД
  { term: 'Барорецепторы', definition: 'Датчики давления в стенке дуги аорты и каротидного синуса. При падении АД учащают ЧСС и сужают сосуды (через симпатику). При повышении — наоборот.', category: 'Регуляция' },
  { term: 'РААС', definition: 'Ренин-ангиотензин-альдостероновая система. Каскад гормонов: при падении АД почки выделяют ренин → ангиотензин II сужает сосуды → альдостерон задерживает натрий и воду. Главный долгосрочный регулятор АД.', category: 'Регуляция' },
  { term: 'Оксид азота (NO)', definition: 'Молекула-вазодилататор, выделяемая эндотелием. Расслабляет гладкую мускулатуру сосудов. База для нитропрепаратов (нитроглицерин).', category: 'Регуляция' },
  { term: 'Эндотелин', definition: 'Молекула-вазоконстриктор, выделяемая эндотелием. Самый мощный из известных. Хроническое повышение — при гипертензии, атеросклерозе, ХБП.', category: 'Регуляция' },
  // Патологии пульса
  { term: 'Парадоксальный пульс', definition: 'Ослабление пульса на вдохе (в норме незначительное, при патологии — выраженное). Признак тампонады сердца, тяжёлой астмы, обструкции ВДП.', category: 'Патология пульса' },
  { term: 'Нитевидный пульс', definition: 'Очень слабый, тонкий пульс — едва ощутим. Признак шока, массивной кровопотери, тяжёлой сердечной недостаточности.', category: 'Патология пульса' },
  { term: 'Пульсовой дефицит', definition: 'ЧСС при аускультации выше, чем частота пульсовых волн на периферии. Бывает при аритмиях (мерцательная аритмия): некоторые сокращения сердца слишком слабые, чтобы дойти до периферии.', category: 'Патология пульса' },
  { term: 'Тампонада сердца', definition: 'Скопление жидкости в полости перикарда, сдавливающее сердце. Пульс парадоксальный, АД низкое, шейные вены набухшие. Экстренное состояние — перикардиоцентез.', category: 'Патология пульса' },
  { term: 'SRR (Sleeping Respiratory Rate)', definition: 'Частота дыхания во сне. Золотой стандарт домашнего мониторинга сердечной недостаточности. Строго < 30 / мин.', category: 'Кардиология' },
]

// ============== ГЛОССАРИЙ ПО ЖКТ ==============
export const GIT_GLOSSARY_TERMS: GlossaryTerm[] = [
  // === Основы и анатомия ===
  { term: 'ЖКТ', latin: 'Трактус гастроинтестиналис', definition: 'Непрерывная мышечная трубка от рта до ануса + ассоциированные паренхиматозные органы (печень, ПЖ). Функция: механическая и химическая обработка пищи, всасывание, выведение.', category: 'Основы' },
  { term: 'Брюшная полость', latin: 'Cavum abdominis', definition: 'Пространство, ограниченное сверху диафрагмой, с боков/снизу — брюшными стенками, сзади — тазовой диафрагмой. Выстлана брюшиной. Содержит органы пищеварения, мочевыделения, репродукции, селезёнку.', category: 'Анатомия' },
  { term: 'Брюшина', latin: 'Peritoneum', definition: 'Серозная оболочка, выстилающая брюшную полость. Висцеральный листок покрывает органы (сероза ЖКТ), париетальный — стенки. «Смазка для органов, чтобы не терлись».', category: 'Анатомия' },
  { term: 'Эпигастрий', definition: 'Область живота непосредственно под мечевидным отростком грудины («под ложечкой»). Зона проекции желудка и поджелудочной железы.', category: 'Анатомия' },
  { term: 'Аборальное направление', definition: 'От рта к анусу («по течению» содержимого). Противоположность — оральное (к рту).', category: 'Анатомия' },
  { term: 'Кардиальный сфинктер', definition: 'Вход в желудок. У собак и кошек слабее человеческого (поэтому могут рвать), но сильнее лошадиного (лошади рвать не могут → риск разрыва желудка при коликах).', category: 'Анатомия' },
  { term: 'Пилорический сфинктер', definition: 'Выход из желудка. Мощный сфинктер-дозатор. При рвоте расслабляется, давая содержимому путь назад в пищевод.', category: 'Анатомия' },
  { term: 'Илеоцекальный клапан', definition: 'Барьер между подвздошной и слепой кишкой. Защищает тонкий кишечник от ретроградного заброса бактерий из толстого. Здесь же всасывается B12.', category: 'Анатомия' },
  { term: 'Гаустры', definition: 'Кармашки-вздутия ободочной кишки для задержки воды. Хорошо выражены у собак, у кошек почти отсутствуют (гладкая трубка).', category: 'Анатомия' },
  { term: 'Параанальные железы', definition: 'Парные мешковидные образования по бокам от анального отверстия. «Парфюмерный отдел» — маркировка территории. Воспаление/закупорка → «ездение на попе».', category: 'Анатомия' },

  // === Гистология стенки ЖКТ ===
  { term: 'Tunica mucosa', definition: 'Слизистая оболочка. Эпителий + Lamina propria (GALT) + Lamina muscularis mucosae. «Рабочая поверхность контакта».', category: 'Гистология' },
  { term: 'Tela submucosa', definition: 'Подслизистая основа. Плотная соединительная ткань с крупными сосудами и Мейснеровым нервным сплетением (секреция, кровоток). «Логистический центр».', category: 'Гистология' },
  { term: 'Tunica muscularis', definition: 'Мышечная оболочка. Внутренний циркулярный + наружный продольный слои гладких мышц. Между ними — Ауэрбахово сплетение (моторика). В желудке есть 3-й косой слой для рвоты.', category: 'Гистология' },
  { term: 'Tunica serosa', definition: 'Серозная оболочка. Висцеральный листок брюшины (мезотелий + соединительная ткань). «Скользкая упаковка» для движения органов.', category: 'Гистология' },
  { term: 'Lamina propria', definition: 'Собственная пластинка слизистой. Рыхлая соединительная ткань под эпителием с сосудами и GALT. Первая линия иммунной обороны ЖКТ.', category: 'Гистология' },
  { term: 'GALT', latin: 'Gut-Associated Lymphoid Tissue', definition: 'Лимфоидная ткань, ассоциированная с кишечником. Миндалины, пейеровы бляшки, солитарные фолликулы. Местный иммунитет ЖКТ.', category: 'Гистология' },
  { term: 'Ворсинки', definition: 'Пальцевидные выросты слизистой тонкой кишки для увеличения площади всасывания. Покрыты энтероцитами с микроворсинками (щеточная каёмка).', category: 'Гистология' },
  { term: 'Крипты Либеркюна', definition: 'Глубокие ямки в слизистой (особенно толстой кишки), где рождаются новые клетки эпителия. В тонкой кишке также есть, но между ворсинками.', category: 'Гистология' },
  { term: 'Энтероциты', definition: 'Рабочие клетки-всасыватели кишечника. Имеют «вход» (апикальная мембрана) и «выход» (базолатеральная в кровь/лимфу).', category: 'Гистология' },
  { term: 'Бокаловидные клетки', definition: 'Клетки-производители слизи (муцина). В толстой кишке их много — чтобы сухой кал скользил и не царапал стенку.', category: 'Гистология' },
  { term: 'Плотные контакты', latin: 'Tight junctions', definition: '«Цемент» между энтероцитами. Не пускают бактерии в кровь. При повреждении → «дырявый кишечник» → транслокация бактерий → сепсис.', category: 'Гистология' },
  { term: 'Париетальные (обкладочные) клетки', definition: 'Клетки желудка, секретируют HCl (денатурация белков, активация пепсина, бактерицидно) и внутренний фактор Касла (для B12).', category: 'Гистология' },
  { term: 'Главные клетки', definition: 'Клетки желудка, секретируют пепсиноген → превращается в пепсин (режет белки).', category: 'Гистология' },
  { term: 'Мукоциты', definition: 'Клетки желудка, секретируют слизь — «броню» от кислоты. Защищают стенку от самопереваривания.', category: 'Гистология' },

  // === Печень и селезёнка — гистология ===
  { term: 'Гепатоциты', definition: 'Основные рабочие клетки печени. Выполняют все функции: синтез белков, детоксикацию, регуляцию сахара, продукцию желчи.', category: 'Гистология печени' },
  { term: 'Портальная триада', definition: 'Структура на углах печёночной дольки: ветвь воротной вены (сырьё из кишечника) + ветвь печёночной артерии (кислород) + желчный проток (отходы).', category: 'Гистология печени' },
  { term: 'Синусоиды печени', definition: 'Особые капилляры с «дырявыми» стенками, позволяют крови свободно контактировать с гепатоцитами. В них сидят Купферовские клетки.', category: 'Гистология печени' },
  { term: 'Купферовские клетки', definition: 'Резидентные макрофаги печени в синусоидах. Поглощают бактерии, токсины, старые эритроциты. «Мухобойка» печени.', category: 'Гистология печени' },
  { term: 'Пространство Диссе', definition: 'Щель между эндотелием синусоидов и гепатоцитами. Здесь происходит обмен веществами между кровью и клеткой печени.', category: 'Гистология печени' },
  { term: 'Красная пульпа', definition: 'Часть селезёнки: синусоиды и тяжи Бильрота. Фильтр крови, разрушение старых эритроцитов.', category: 'Гистология селезёнки' },
  { term: 'Белая пульпа', definition: 'Лимфоидная ткань селезёнки вокруг артерий (PALS). Т- и В-лимфоциты, антитела. «Армия» селезёнки.', category: 'Гистология селезёнки' },

  // === Поджелудочная — гистология ===
  { term: 'Ацинус', definition: 'Структурная единица экзокринной части ПЖ. Скопление клеток в форме виноградной грозди. Производит пищеварительные ферменты.', category: 'Гистология ПЖ' },
  { term: 'Островки Лангерганса', definition: 'Эндокринная часть ПЖ (2% ткани). Скопления клеток среди ацинусов. Бета → инсулин, альфа → глюкагон, дельта → соматостатин.', category: 'Гистология ПЖ' },
  { term: 'Зимогены', definition: 'Неактивные предшественники ферментов ПЖ (трипсиноген, химотрипсиноген). «Спящие агенты». Опасны при преждевременной активации внутри железы → аутолиз.', category: 'Гистология ПЖ' },
  { term: 'Энтерокиназа', definition: 'Фермент 12-перстной кишки. «Будит» трипсиноген → трипсин. Трипсин активирует остальные зимогены. Ключевой шаг защиты от аутолиза.', category: 'Физиология' },

  // === Физиология ЖКТ ===
  { term: 'Перистальтика', definition: 'Волнообразные сокращения мышечной оболочки, продвигающие содержимое вперёд (от рта к анусу).', category: 'Физиология' },
  { term: 'Сегментация', definition: 'Локальные сокращения кишечника для перемешивания химуса с соками без продвижения вперёд.', category: 'Физиология' },
  { term: 'ММК (мигрирующий моторный комплекс)', definition: 'Цикл мощных сокращений в период голода. Функция «уборка»: выметание остатков и бактерий в толстую кишку, предотвращение СИБР.', category: 'Физиология' },
  { term: 'Химус', definition: 'Пищевая кашица в кишечнике. Формируется в желудке из еды + желудочный сок, далее продвигается по кишке.', category: 'Физиология' },
  { term: 'Сурфактант желудка? — нет', definition: 'В ЖКТ сурфактанта нет. Зато слизь мукоцитов защищает стенку желудка от HCl.', category: 'Физиология' },
  { term: 'SGLT1', definition: 'Транспортер глюкозы/галактозы в энтероцитах. Вторично-активный транспорт с натрием. Нет Na — нет всасывания сахара!', category: 'Физиология' },
  { term: 'Хиломикроны', definition: 'Транспортные частицы жира в энтероцитах. Слишком велики для крови → выходят в лимфу (млечные сосуды), минуя печень на первом этапе.', category: 'Физиология' },
  { term: 'Внутренний фактор Касла', definition: 'Гликопротеин, вырабатываемый париетальными клетками желудка. Связывается с B12 для всасывания в подвздошной кишке.', category: 'Физиология' },
  { term: 'Ворсинка vs крипта', definition: 'В тонкой кишке есть ворсинки (всасывание) и крипты (рождение клеток). В толстой — крипты есть, ворсинок НЕТ.', category: 'Гистология' },

  // === Печень — физиология ===
  { term: 'Желчь', definition: 'Секрет печени для эмульгации жиров (разбивает капли → увеличивает площадь для липазы). Ферментов в желчи НЕТ! Только желчные кислоты + билирубин.', category: 'Физиология' },
  { term: 'Стеркобилин', definition: 'Пигмент, делающий кал коричневым. Производное билирубина (из желчи). Нет желчи → ахолия (серый/белый кал).', category: 'Физиология' },
  { term: 'Цикл Кребса-Хензелейта', definition: 'Орнитиновый цикл в печени. Превращает ядовитый аммиак (NH3) в безопасную мочевину (для выделения почками).', category: 'Физиология' },
  { term: 'Система P450', definition: 'Система ферментов печени (цитохром P450), обезвреживающая лекарства и ксенобиотики. База метаболизма медикаментов.', category: 'Физиология' },

  // === Аппетит и жажда — гормоны и регуляция ===
  { term: 'Грелин', definition: '«Гормон голода». Вырабатывается пустым желудком, будит NPY-нейроны в дугообразном ядре гипоталамуса → заставляет искать еду.', category: 'Гормоны' },
  { term: 'Лептин', definition: 'Гормон сытости от жировой ткани (адипоцитов). Чем больше жира — тем больше лептина → мозг отключает голод. У ожиревших — лептинорезистентность.', category: 'Гормоны' },
  { term: 'Инсулин', definition: 'Гормон бета-клеток островков Лангерганса. Снижает сахар в крови. Также работает как сигнал сытости для мозга.', category: 'Гормоны' },
  { term: 'Глюкагон', definition: 'Гормон альфа-клеток островков Лангерганса. Повышает сахар: печень отдаёт гликоген. Антагонист инсулина.', category: 'Гормоны' },
  { term: 'CCK (холецистокинин)', definition: 'Гормон кишечника. Выделяется при поступлении жиров/белков. Говорит мозгу: «Хватит, мы заняты перевариванием» (сигнал сытости).', category: 'Гормоны' },
  { term: 'PYY (пептид YY)', definition: 'Гормон кишечника. Вместе с CCK даёт сигнал «СТОП» мозгу. Секретируется в подвздошной/толстой кишке.', category: 'Гормоны' },
  { term: 'NPY (нейропептид Y)', definition: 'Орексигенный нейропептид дугообразного ядра. «Ешь! Копи энергию!». Антагонист POMC.', category: 'Гормоны' },
  { term: 'POMC', definition: 'Анорексигенный нейропептид дугообразного ядра. Превращается в α-MSH. «Стоп! Ты сыт!».', category: 'Гормоны' },
  { term: 'АДГ (вазопрессин)', definition: 'Гормон-«берегатель воды». Заставляет почки всасывать воду обратно в кровь, делая мочу концентрированной. Выделяется при жажде.', category: 'Гормоны' },
  { term: 'Цитокины (ФНО-α, ИЛ-1, ИЛ-6)', definition: 'Вещества воспаления. Проникают в гипоталамус и «выключают» аппетит во время болезни, чтобы организм боролся с инфекцией, а не переваривал обед.', category: 'Гормоны' },
  { term: 'РААС', definition: 'Ренин-ангиотензин-альдостероновая система. При падении объёма крови → ренин → ангиотензин II → жажда + сужение сосудов + альдостерон (задержка Na).', category: 'Регуляция' },
  { term: 'Осмолярность', definition: 'Концентрация растворенных частиц (солей, сахара) в крови. Чем выше — тем сильнее жажда (через осморецепторы).', category: 'Регуляция' },
  { term: 'Осморецепторы', definition: 'Нейроны переднего гипоталамуса в зонах без ГЭБ. При высокой осмолярности вода выходит из них → сморщиваются (как изюм) → сигнал жажды + АДГ.', category: 'Регуляция' },
  { term: 'Барорецепторы', definition: 'Датчики давления в дуге аорты, каротидном синусе, предсердиях. Реагируют на объём крови: мало крови → жажда.', category: 'Регуляция' },
  { term: 'CTZ (хеморецепторная триггерная зона)', definition: 'Участок в area postrema продолговатого мозга, лишённый ГЭБ (капилляры фенестрированные). «Химический датчик» крови на токсины → запускает рвоту.', category: 'Регуляция' },
  { term: 'Рвотный центр (VC)', definition: '«Дирижёр» в продолговатом мозге. Сам не чувствует токсины — только получает сигналы (от CTZ, вагуса) и командует мышцам: тошнить, тужиться, открывать сфинктеры.', category: 'Регуляция' },
  { term: 'Гематоэнцефалический барьер (ГЭБ)', definition: 'Защитный фильтр между кровью и мозгом. В зоне CTZ отсутствует — это позволяет токсинам напрямую стимулировать рвотный рефлекс.', category: 'Регуляция' },

  // === Состояния аппетита и жажды ===
  { term: 'Нормопексия', definition: 'Нормальный аппетит. Все системы работают штатно.', category: 'Клиническое' },
  { term: 'Нормодипсия', definition: 'Нормальное потребление воды.', category: 'Клиническое' },
  { term: 'Гипорексия', definition: 'Сниженный аппетит. Животное ест, но вяло, выборочно, без энтузиазма.', category: 'Клиническое' },
  { term: 'Анорексия', definition: 'Полное отсутствие желания есть. Истинная: мозг не посылает «голод» (ЦНС). Псевдо: голод есть, но есть мешает боль/тошнота/механика.', category: 'Клиническое' },
  { term: 'Полифагия', definition: 'Патологически сильный голод («жор»). Характерен для диабета, гипертиреоза, Кушинга, мальабсорбции/ЭНПЖ.', category: 'Клиническое' },
  { term: 'Полидипсия', definition: 'Патологически сильная жажда. Главный симптом диабета и болезней почек. Маркер: >90-100 мл/кг/сут (собаки), >45-50 (кошки).', category: 'Клиническое' },
  { term: 'Полиурия', definition: 'Патологически обильное мочеотделение. Часто идёт в паре с полидипсией (ПУ/ПД-синдром).', category: 'Клиническое' },

  // === Рвота ===
  { term: 'Рвота (Emesis)', definition: 'Активный, ЦНС-контролируемый акт. Есть фаза тошноты, работают мышцы пресса, диафрагма напряжена. Содержимое выходит под давлением.', category: 'Рвота' },
  { term: 'Регургитация', definition: 'Пассивное вытекание непереваренного содержимого из пищевода. Нет тошноты, нет напряжения мышц. Форма «колбаски». Часто сразу после еды.', category: 'Рвота' },
  { term: 'Дисфагия', definition: 'Затруднённое глотание. Многократные глотательные движения, вытягивание шеи, кашель при приёме пищи.', category: 'Клиническое' },
  { term: 'Гиперсаливация', definition: 'Обильное выделение слюны перед рвотой. Защитный механизм: смыть кислоту с зубов, смягчить проход для рвотных масс.', category: 'Рвота' },
  { term: 'Экспульсия', definition: 'Третья фаза рвотного акта: открытие голосовой щели + форсированный выброс содержимого желудка наружу под давлением мышц пресса.', category: 'Рвота' },
  { term: 'Метаболический алкалоз', definition: 'Сдвиг pH крови в щелочную сторону. Классическое последствие потери HCl при частой желудочной рвоте.', category: 'Рвота' },
  { term: 'Парадоксальная ацидурия', definition: 'Моча кислая на фоне системного алкалоза крови. Возникает при дефиците K/Cl: почки выделяют H+ вместо K+, чтобы сохранить Na+ и объём крови.', category: 'Рвота' },
  { term: 'Синдром Мэллори-Вейсса', definition: 'Продольные разрывы слизистой оболочки в месте перехода пищевода в желудок, вызванные резким повышением давления при рвоте. Проявляется алой кровью.', category: 'Рвота' },
  { term: 'Аспирационная пневмония', definition: 'Тяжёлое воспаление лёгких при попадании рвотных масс (особенно кислых) в дыхательные пути. Химический ожог альвеол + бактериальная инфекция. Смертельно опасно.', category: 'Рвота' },

  // === Патологии ЖКТ ===
  { term: 'Аутолиз', definition: 'Самопереваривание тканей собственными ферментами. Главная причина боли и некроза при панкреатите (трипсин активируется внутри железы).', category: 'Патология' },
  { term: 'Илеус', definition: 'Непроходимость кишечника. Механическая (инородное тело, инвагинация, заворот) или паралитическая (двигатель сломался — перитонит, гипокалиемия).', category: 'Патология' },
  { term: 'Инвагинация', definition: '«Кишка в кишке» (как телескоп). Один участок внедряется в другой. Механическая непроходимость, требует хирургии.', category: 'Патология' },
  { term: 'Транслокация бактерий', definition: 'Проникновение бактерий из кишечника в кровоток через повреждённые плотные контакты («дырявый кишечник»). Приводит к сепсису.', category: 'Патология' },
  { term: 'СИБР', latin: 'Синдром избыточного бактериального роста', definition: 'Избыточный рост бактерий в тонкой кишке. Возникает при нарушении ММК (нет «уборки»). Бактерии деконъюгируют желчь, воруют B12.', category: 'Патология' },
  { term: 'Мальдигестия', definition: 'Нарушение расщепления пищи. Нет ферментов или желчи. Еда не расщепилась до всасывания.', category: 'Патология' },
  { term: 'Мальабсорбция', definition: 'Нарушение всасывания. Еда расщепилась, но не всосалась (повреждена слизистая, ВЗК, лимфома).', category: 'Патология' },
  { term: 'Асцит', definition: 'Скопление жидкости в брюшной полости («водяной шар»). Причины: портальная гипертензия (цирроз), сердечная недостаточность, гипоальбуминемия.', category: 'Патология' },

  // === Диарея и стул ===
  { term: 'Осмотическая диарея', definition: 'Вещества в просвете тянут воду (магнит). Лактоза, непереваренный жир при ЭНПЖ. Тест: голодание → диарея прекращается.', category: 'Диарея' },
  { term: 'Секреторная диарея', definition: 'Токсины бактерий заставляют клетки активно выбрасывать воду и соли наружу («кран открыт»). Голодание НЕ помогает.', category: 'Диарея' },
  { term: 'Экссудативная диарея', definition: 'Диарея с кровью и гноем из-за разрушения стенки кишки (воспаление, вирус, ВЗК, рак). Признаки: слизь, кровь, температура.', category: 'Диарея' },
  { term: 'Моторная диарея', definition: 'Кишечник сокращается так быстро, что вода не успевает всосаться («скоростной поезд»). Причина: гипертиреоз у кошек.', category: 'Диарея' },
  { term: 'Мелена', definition: 'Чёрный, дегтеобразный стул с характерным зловонным сладковато-гнилостным запахом. Указывает на переваривание крови из верхних отделов ЖКТ (желудок, тонкая кишка).', category: 'Стул' },
  { term: 'Гематохезия', definition: 'Алая кровь в кале. Кровотечение «снизу» (толстая кишка, прямая, анус). Кровь не успела перевариться.', category: 'Стул' },
  { term: 'Ахолия', definition: 'Отсутствие желчи в кишечнике. Кал становится белым/серым (глина), так как нет пигмента стеркобилина. Закупорка желчных путей или болезнь печени.', category: 'Стул' },
  { term: 'Стеаторея', definition: 'Выделение с калом избыточного жира. Кал блестит, плохо смывается, зловонный. Признак мальдигестии (нехватка липазы ПЖ при ЭНПЖ) или отсутствия желчи.', category: 'Стул' },
  { term: 'Тенезмы', definition: 'Ложные, болезненные позывы к дефекации. Характерны для колита (воспаления толстой кишки).', category: 'Стул' },
  { term: 'Дисхезия', definition: 'Болезненный акт дефекации. Часто из-за воспаления ануса или параанальных желёз.', category: 'Стул' },
  { term: 'Копростаз', definition: 'Застой и уплотнение каловых масс в толстой или прямой кишке. Кал стоит и сохнет, превращаясь в камень. Предшественник истинного запора.', category: 'Стул' },
  { term: 'Мегаколон', definition: 'Патологическое расширение и атония (потеря тонуса) толстой кишки, чаще у кошек. Кишка заполнена огромным количеством сухого кала. Слабительные не помогают — нужна хирургия или ручная чистка.', category: 'Патология' },
  { term: 'КЦЖК (бутират)', definition: 'Короткоцепочечные жирные кислоты, производимые бактериями толстой кишки из клетчатки. Главное топливо для колоноцитов. Нет бутирата → «дырявый кишечник».', category: 'Физиология' },
  { term: 'Колоноциты', definition: 'Рабочие клетки толстой кишки, всасывающие воду. Питаются бутиратом (КЦЖК) от бактерий.', category: 'Гистология' },

  // === Патологии печени ===
  { term: 'Липидоз (стеатоз)', definition: 'Накопление жира в гепатоцитах. Макровакуолярный стеатоз. Критично для кошек при голодании >48 ч (нет карнитина/аполипопротеинов для экспорта жира). Печень становится бледно-жёлтой, дряблой.', category: 'Патология печени' },
  { term: 'Портосистемный шунт (PSS)', definition: 'Аномальный сосуд, пускающий кровь из кишечника мимо печени. Токсины (аммиак) не фильтруются → печёночная энцефалопатия (судороги, странное поведение). Печень маленькая (микрогепатия).', category: 'Патология печени' },
  { term: 'Микрогепатия', definition: 'Маленький размер печени. Характерен для шунтов (атрофия из-за отсутствия притока крови из воротной вены) и цирроза.', category: 'Патология печени' },
  { term: 'Цирроз', definition: 'Замена нормальной ткани печени рубцовой (фиброзной). Печень маленькая, твёрдая, бугристая, как камень. Портальная гипертензия → асцит.', category: 'Патология печени' },
  { term: 'Гепатомегалия', definition: 'Патологическое увеличение размеров печени. Край выступает за последнюю реберную дугу более чем на 2–3 см. Причины: липидоз, гепатит, опухоль.', category: 'Патология печени' },
  { term: 'Экстрамедуллярный гемопоэз', definition: 'Производство клеток крови вне костного мозга (в селезёнке, печени) при тяжёлых заболеваниях. Запасной завод крови.', category: 'Патология' },

  // === Патологии селезёнки ===
  { term: 'Спленомегалия', definition: 'Увеличение селезёнки. Диффузная: ХСН (застой крови), сепсис, лимфома. Узловая: гематома, гиперплазия, гемангиосаркома.', category: 'Патология селезёнки' },
  { term: 'Гемангиосаркома', definition: 'Злокачественная опухоль из клеток сосудов селезёнки. Очень опасна внезапным разрывом и внутренним кровотечением. Часто у крупных собак (немецкие овчарки).', category: 'Патология селезёнки' },
  { term: 'Заворот селезёнки', latin: 'Splenic Torsion', definition: 'Перекрут органа вокруг своей оси. Артерии качают кровь внутрь, вены пережаты → застой → селезёнка надувается, становится чёрно-багровой (некроз/инфаркт). Срочно удалять.', category: 'Патология селезёнки' },

  // === Поджелудочная — патологии и маркёры ===
  { term: 'Панкреатит', definition: 'Воспаление поджелудочной. Преждевременная активация трипсина внутри железы → аутолиз → отёк → сдавление протоков → порочный круг. Причины: жирная еда (собаки), травма, лекарства, гиперлипидемия.', category: 'Патология ПЖ' },
  { term: 'ЭНПЖ', latin: 'Экзокринная недостаточность поджелудочной железы', definition: 'Ацинусы атрофируются (генетика у немецких овчарок или хронический панкреатит). Нет ферментов → стеаторея + полифагия + похудение + копрофагия.', category: 'Патология ПЖ' },
  { term: 'cPL/fPL', latin: 'Canine/Feline Pancreatic Lipase', definition: 'Панкреатическая липаза — специфичный маркер панкреатита. Рост ×3 и более от нормы — диагноз. Иммунорецепторный тест (SNAP) или спектрофотометрия.', category: 'Биомаркёры' },
  { term: 'Сахарный диабет', definition: 'Эндокринный сбой ПЖ. Тип I (собаки): разрушение бета-клеток, нет инсулина. Тип II (кошки): инсулинорезистентность на фоне ожирения. Симптомы: ПУ/ПД, похудение при полифагии.', category: 'Патология ПЖ' },

  // === Клинический осмотр ===
  { term: 'Галитоз', definition: 'Неприятный запах из ротовой полости. Гнилостный (пародонтит), аммиачный (уремия), ацетоновый/фруктовый (диабетический кетоацидоз), кислый (рефлюкс из желудка).', category: 'Клиническое' },
  { term: 'Уремические язвы', definition: 'Эрозии и язвы на слизистой рта (язык, десны) при тяжёлой почечной недостаточности. Токсины (мочевина) выходят через слизистую и обжигают её. Серовато-белые с красным ободком.', category: 'Клиническое' },
  { term: 'Линейное инородное тело', definition: 'Длинные тонкие предметы (нитки, ёлочная мишура). Фиксируются под языком → кишечник собирается «гармошкой» по нити. Классика у кошек. ВСЕГДА поднимать язык у рвущего пациента!', category: 'Клиническое' },
  { term: 'Иктеричность (желтуха)', definition: 'Жёлтое окрашивание слизистых (склер, уздечки языка) и кожи из-за повышения билирубина в крови. Дифференцируют: до печени / в печени / после печени.', category: 'Клиническое' },
  { term: 'Мегаэзофагус', definition: 'Патологическое расширение пищевода с атонией. Еда не проходит нормально → регургитация «колбаской» сразу после еды. Риск аспирационной пневмонии.', category: 'Патология' },
  { term: 'Поза «молящегося»', definition: 'Передние лапы вытянуты, задние стоят. Снижает натяжение брыжейки и уменьшает боль в эпигастрии. Классический признак панкреатита.', category: 'Клиническое' },
  { term: 'Доскообразный живот', definition: 'Защитное напряжение мышц брюшной стенки при пальпации. Признак перитонита. Пальпацию нужно прекратить!', category: 'Клиническое' },
]
